{"op":"add","path":"/elements/main","value":{"type":"LayoutRow","props":{},"children":["child-1","list"]}}
{"op":"add","path":"/elements/child-1","value":{"type":"LayoutColumn","props":{},"children":[]}}
{"op":"add","path":"/elements/list","value":{"type":"LayoutRow","props":{},"repeat":{"statePath":"/items","key":"id"},"children":["item"]}}
{"op":"add","path":"/elements/item","value":{"type":"LayoutColumn","props":{},"children":[]}}
{"op":"add","path":"/state/items","value":[]}
{"op":"add","path":"/state/items/0","value":{"id":"1","title":"First Item"}}
{"op":"add","path":"/state/items/1","value":{"id":"2","title":"Second Item"}}

Note: state patches appear right after the elements that use them, so the UI fills in as it streams. ONLY use component types from the AVAILABLE COMPONENTS list below.

